with filtered as (select id, store_name, city, region, opened_date, round(sqft * 0.9, 2) as adjusted_sqft, concat(city, '/', region) as city_region from stores where sqft > 11803) select id, region, opened_date, city_region, cume_dist() over (partition by city, region order by adjusted_sqft) as adjusted_sqft_cume_dist, sum(adjusted_sqft) over (partition by region order by opened_date, id rows between unbounded preceding and current row) as cumulative_adjusted_sqft, lead(adjusted_sqft, 1) over (partition by city order by opened_date, id) as next_adjusted_sqft from filtered
